/** 三态查询范围：默认含本问族（自身+祖先），不含其它根问 */
export type KeyStatusScope = {
  queryKey?: string
  /** 默认 true：含 listQuerySelfAndAncestors；false 仅本 qk */
  includeFamily?: boolean
}

